=Extract all entities and relationships from this text. Return valid JSON:

{
  "entities": [{"id": "e1", "name": "...", "type": "Person|Organization|Concept|Place|Event|Technology", "description": "brief"}],
  "relationships": [{"source": "e1", "target": "e2", "type": "works_for|created|related_to|part_of|uses|located_in", "description": "brief"}]
}

Text:
{{ $json.body.text }}

parameters.jsCode:
const items = $input.all();
const content = items[0].json.message.content;

let graph;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/s);
  graph = jsonMatch ? JSON.parse(jsonMatch[0]) : { entities: [], relationships: [] };
} catch (e) {
  graph = { entities: [], relationships: [] };
}

// Build adjacency info
const entityMap = {};
for (const entity of graph.entities) {
  entityMap[entity.id] = { ...entity, connections: 0 };
}

for (const rel of graph.relationships) {
  if (entityMap[rel.source]) entityMap[rel.source].connections++;
  if (entityMap[rel.target]) entityMap[rel.target].connections++;
}

// Prepare nodes sheet data
const nodes = graph.entities.map(e => ({
  id: e.id,
  name: e.name,
  type: e.type,
  description: e.description || '',
  connections: entityMap[e.id] ? entityMap[e.id].connections : 0
}));

// Prepare edges sheet data
const edges = graph.relationships.map((r, i) => ({
  edge_id: `r${i+1}`,
  source_id: r.source,
  source_name: entityMap[r.source] ? entityMap[r.source].name : r.source,
  target_id: r.target,
  target_name: entityMap[r.target] ? entityMap[r.target].name : r.target,
  relationship: r.type,
  description: r.description || ''
}));

return [{
  json: {
    entityCount: nodes.length,
    relationshipCount: edges.length,
    nodes,
    edges,
    entityTypes: [...new Set(nodes.map(n => n.type))],
    relationshipTypes: [...new Set(edges.map(e => e.relationship))]
  }
}];
